import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import {
  ArrowLeft,
  ArrowRight,
  Check,
  CheckCircle2,
  Hash,
  Loader2,
  ShieldCheck,
  Sparkles,
  X,
} from 'lucide-react';
import { supabase } from '@/lib/supabase';
import { appToast } from '@/lib/feedback';
import {
  isCommunityOnboardingStepComplete,
  type CommunityOnboardingAnswer,
  type CommunityOnboardingAnswers,
  type CommunityOnboardingFlow,
} from '@/lib/communityOnboarding';

interface CommunityOnboardingModalProps {
  communityId: string;
  communityName: string;
  communityLogoUrl?: string | null;
  communityRules?: string | null;
  flow: CommunityOnboardingFlow;
  channels: Array<{ id: string; name: string; type?: string | null }>;
  userId: string;
  onComplete: (preferredChannelId?: string) => void;
}

interface ProgressRecord {
  answers: CommunityOnboardingAnswers | null;
  completed_step_ids: string[] | null;
  last_step_id: string | null;
  completed_at: string | null;
}

const asAnswers = (value: unknown): CommunityOnboardingAnswers => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const answers: CommunityOnboardingAnswers = {};
  Object.entries(value as Record<string, unknown>).forEach(([key, answer]) => {
    if (typeof answer === 'boolean' || typeof answer === 'string') answers[key] = answer;
    if (Array.isArray(answer)) answers[key] = answer.filter((item): item is string => typeof item === 'string');
  });
  return answers;
};

export const CommunityOnboardingModal: React.FC<CommunityOnboardingModalProps> = ({
  communityId,
  communityName,
  communityLogoUrl,
  communityRules,
  flow,
  channels,
  userId,
  onComplete,
}) => {
  const reduceMotion = useReducedMotion();
  const closeButtonRef = useRef<HTMLButtonElement>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  const [completed, setCompleted] = useState(false);
  const [stepIndex, setStepIndex] = useState(0);
  const [answers, setAnswers] = useState<CommunityOnboardingAnswers>({});
  const [completedStepIds, setCompletedStepIds] = useState<string[]>([]);
  const currentStep = flow.steps[stepIndex];
  const currentAnswer = currentStep ? answers[currentStep.id] : undefined;
  const canContinue = currentStep ? isCommunityOnboardingStepComplete(currentStep, currentAnswer) : false;
  const progress = flow.steps.length > 0 ? Math.round(((stepIndex + 1) / flow.steps.length) * 100) : 0;

  const availableChannels = useMemo(
    () => channels.filter((channel) => channel.type !== 'voice' && channel.type !== 'video'),
    [channels],
  );

  useEffect(() => {
    if (!flow.enabled || flow.steps.length === 0 || !userId) {
      setLoading(false);
      return;
    }
    let active = true;
    const loadProgress = async () => {
      setLoading(true);
      const { data, error } = await supabase
        .from('community_onboarding_progress')
        .select('answers, completed_step_ids, last_step_id, completed_at')
        .eq('community_id', communityId)
        .eq('user_id', userId)
        .maybeSingle();
      if (!active) return;
      if (error) {
        console.error('Could not load community onboarding progress:', error);
        setLoading(false);
        return;
      }
      const progressRecord = data as ProgressRecord | null;
      if (progressRecord?.completed_at) {
        setCompleted(true);
      } else if (progressRecord) {
        setAnswers(asAnswers(progressRecord.answers));
        setCompletedStepIds(Array.isArray(progressRecord.completed_step_ids) ? progressRecord.completed_step_ids : []);
        const savedIndex = flow.steps.findIndex((step) => step.id === progressRecord.last_step_id);
        if (savedIndex >= 0) setStepIndex(savedIndex);
      }
      setLoading(false);
    };
    void loadProgress();
    return () => { active = false; };
  }, [communityId, flow.enabled, flow.steps, userId]);

  useEffect(() => {
    if (loading || dismissed || completed) return;
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setDismissed(true);
    };
    document.addEventListener('keydown', handleEscape);
    window.requestAnimationFrame(() => closeButtonRef.current?.focus());
    return () => document.removeEventListener('keydown', handleEscape);
  }, [completed, dismissed, loading]);

  const setAnswer = (answer: CommunityOnboardingAnswer) => {
    if (!currentStep) return;
    setAnswers((current) => ({ ...current, [currentStep.id]: answer }));
  };

  const persistProgress = async (input: {
    nextStepId: string | null;
    nextCompletedStepIds: string[];
    completedAt?: string | null;
  }) => {
    const { error } = await supabase
      .from('community_onboarding_progress')
      .upsert({
        community_id: communityId,
        user_id: userId,
        answers,
        completed_step_ids: input.nextCompletedStepIds,
        last_step_id: input.nextStepId,
        completed_at: input.completedAt ?? null,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'community_id,user_id' });
    if (error) throw error;
  };

  const continueFlow = async () => {
    if (!currentStep || !canContinue || saving) return;
    setSaving(true);
    const nextCompletedStepIds = Array.from(new Set([...completedStepIds, currentStep.id]));
    const isLastStep = stepIndex >= flow.steps.length - 1;
    const nextStep = isLastStep ? null : flow.steps[stepIndex + 1];
    try {
      await persistProgress({
        nextStepId: nextStep?.id || null,
        nextCompletedStepIds,
        ...(isLastStep ? { completedAt: new Date().toISOString() } : {}),
      });
      setCompletedStepIds(nextCompletedStepIds);
      if (isLastStep) {
        const selectedChannels = Object.entries(answers)
          .filter(([stepId]) => flow.steps.find((step) => step.id === stepId)?.type === 'channels')
          .flatMap(([, answer]) => Array.isArray(answer) ? answer : []);
        setCompleted(true);
        onComplete(selectedChannels[0]);
        appToast('Community setup completed.', 'success');
      } else {
        setStepIndex((index) => index + 1);
      }
    } catch (error) {
      console.error('Could not save community onboarding progress:', error);
      appToast('Your onboarding progress could not be saved. Please try again.', 'error');
    } finally {
      setSaving(false);
    }
  };

  const goBack = () => setStepIndex((index) => Math.max(0, index - 1));

  if (!flow.enabled || flow.steps.length === 0 || loading || dismissed || completed || !currentStep) return null;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-[90] flex items-center justify-center bg-black/75 p-2 backdrop-blur-xl sm:p-6">
        <motion.div
          initial={reduceMotion ? false : { opacity: 0, scale: 0.97, y: 18 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.98, y: 10 }}
          transition={{ duration: reduceMotion ? 0 : 0.22, ease: 'easeOut' }}
          role="dialog"
          aria-modal="true"
          aria-labelledby="community-onboarding-step-title"
          className="relative flex h-[min(760px,calc(100dvh-1rem))] w-full max-w-4xl overflow-hidden rounded-[30px] border border-white/10 bg-[#f5f5f7] text-zinc-950 shadow-2xl sm:h-[min(760px,calc(100dvh-3rem))] sm:rounded-[38px]"
        >
          <div className="pointer-events-none absolute -left-24 -top-40 h-96 w-96 rounded-full bg-indigo-300/35 blur-3xl" />
          <aside className="relative hidden w-[270px] shrink-0 flex-col border-r border-black/[0.06] bg-white/55 p-7 backdrop-blur-2xl md:flex">
            <div className="flex items-center gap-3">
              <div className="grid h-11 w-11 place-items-center overflow-hidden rounded-2xl bg-zinc-950 text-base font-bold text-white shadow-lg">
                {communityLogoUrl ? <img src={communityLogoUrl} alt="" className="h-full w-full object-cover" /> : communityName.slice(0, 1).toUpperCase()}
              </div>
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold">{communityName}</p>
                <p className="text-xs text-zinc-400">Powered by Wersee</p>
              </div>
            </div>
            <ol className="mt-10 space-y-2">
              {flow.steps.map((step, index) => {
                const active = index === stepIndex;
                const done = completedStepIds.includes(step.id) || index < stepIndex;
                return (
                  <li key={step.id} className={`flex items-center gap-3 rounded-2xl px-3 py-3 text-sm transition ${active ? 'bg-white font-semibold shadow-sm' : 'text-zinc-400'}`}>
                    <span className={`grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs ${done ? 'bg-emerald-500 text-white' : active ? 'bg-zinc-950 text-white' : 'bg-black/[0.05]'}`}>
                      {done ? <Check className="h-3.5 w-3.5" /> : index + 1}
                    </span>
                    <span className="truncate">{step.title}</span>
                  </li>
                );
              })}
            </ol>
            <div className="mt-auto rounded-3xl bg-zinc-950 p-5 text-white">
              <Sparkles className="h-5 w-5 text-indigo-300" />
              <p className="mt-3 text-sm font-semibold">{flow.title}</p>
              <p className="mt-1 text-xs leading-5 text-white/45">{flow.subtitle}</p>
            </div>
          </aside>

          <main className="relative flex min-w-0 flex-1 flex-col">
            <div className="flex items-center gap-4 px-5 pb-4 pt-5 sm:px-8 sm:pt-7">
              <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-black/[0.06]">
                <motion.div className="h-full rounded-full bg-zinc-950" animate={{ width: `${progress}%` }} transition={{ duration: reduceMotion ? 0 : 0.22 }} />
              </div>
              <span className="text-xs font-semibold tabular-nums text-zinc-400">{stepIndex + 1}/{flow.steps.length}</span>
              <button
                ref={closeButtonRef}
                type="button"
                onClick={() => setDismissed(true)}
                className="grid h-10 w-10 place-items-center rounded-full bg-white/70 text-zinc-500 shadow-sm transition hover:bg-white hover:text-black focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500"
                aria-label="Continue onboarding later"
              >
                <X className="h-4 w-4" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto px-5 pb-4 sm:px-8">
              <AnimatePresence mode="wait" initial={false}>
                <motion.div
                  key={currentStep.id}
                  initial={reduceMotion ? false : { opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={reduceMotion ? { opacity: 0 } : { opacity: 0, x: -12 }}
                  transition={{ duration: reduceMotion ? 0 : 0.18 }}
                  className="mx-auto max-w-xl py-5 sm:py-8"
                >
                  <div className="grid h-14 w-14 place-items-center rounded-[20px] bg-zinc-950 text-white shadow-xl shadow-black/15 sm:h-16 sm:w-16">
                    {currentStep.type === 'rules' ? <ShieldCheck className="h-6 w-6" /> : currentStep.type === 'channels' ? <Hash className="h-6 w-6" /> : currentStep.type === 'finish' ? <CheckCircle2 className="h-6 w-6" /> : <Sparkles className="h-6 w-6" />}
                  </div>
                  <p className="mt-7 text-[10px] font-bold uppercase tracking-[0.2em] text-indigo-600">{flow.title}</p>
                  <h1 id="community-onboarding-step-title" className="mt-2 text-3xl font-semibold tracking-[-0.035em] sm:text-4xl">{currentStep.title}</h1>
                  <p className="mt-3 text-sm leading-6 text-zinc-500 sm:text-base sm:leading-7">{currentStep.description}</p>

                  {(currentStep.type === 'single_choice' || currentStep.type === 'multi_choice') && (
                    <fieldset className="mt-7 space-y-2.5">
                      <legend className="sr-only">{currentStep.title}</legend>
                      {currentStep.options.map((option) => {
                        const selected = currentStep.type === 'single_choice'
                          ? currentAnswer === option.id
                          : Array.isArray(currentAnswer) && currentAnswer.includes(option.id);
                        return (
                          <label key={option.id} className={`flex min-h-16 cursor-pointer items-center gap-4 rounded-[20px] border bg-white px-4 py-3 shadow-sm transition ${selected ? 'border-indigo-300 ring-4 ring-indigo-500/10' : 'border-black/[0.06] hover:border-black/15'}`}>
                            <input
                              type={currentStep.type === 'single_choice' ? 'radio' : 'checkbox'}
                              name={`onboarding-${currentStep.id}`}
                              checked={selected}
                              onChange={() => {
                                if (currentStep.type === 'single_choice') setAnswer(option.id);
                                else {
                                  const current = Array.isArray(currentAnswer) ? currentAnswer : [];
                                  setAnswer(selected ? current.filter((id) => id !== option.id) : [...current, option.id]);
                                }
                              }}
                              className="sr-only"
                            />
                            <span className={`grid h-6 w-6 shrink-0 place-items-center ${currentStep.type === 'single_choice' ? 'rounded-full' : 'rounded-lg'} border-2 ${selected ? 'border-indigo-500 bg-indigo-500 text-white' : 'border-zinc-200'}`}>
                              {selected && <Check className="h-3.5 w-3.5" />}
                            </span>
                            <span>
                              <span className="block text-sm font-semibold text-zinc-900">{option.label}</span>
                              {option.description && <span className="mt-0.5 block text-xs text-zinc-400">{option.description}</span>}
                            </span>
                          </label>
                        );
                      })}
                    </fieldset>
                  )}

                  {currentStep.type === 'channels' && (
                    <fieldset className="mt-7 grid gap-2.5 sm:grid-cols-2">
                      <legend className="sr-only">Recommended channels</legend>
                      {availableChannels.filter((channel) => currentStep.channelIds.includes(channel.id)).map((channel) => {
                        const selectedChannels = Array.isArray(currentAnswer) ? currentAnswer : [];
                        const selected = selectedChannels.includes(channel.id);
                        return (
                          <label key={channel.id} className={`flex min-h-16 cursor-pointer items-center gap-3 rounded-[20px] border bg-white px-4 shadow-sm transition ${selected ? 'border-indigo-300 ring-4 ring-indigo-500/10' : 'border-black/[0.06] hover:border-black/15'}`}>
                            <input
                              type="checkbox"
                              checked={selected}
                              onChange={() => setAnswer(selected ? selectedChannels.filter((id) => id !== channel.id) : [...selectedChannels, channel.id])}
                              className="sr-only"
                            />
                            <span className={`grid h-9 w-9 place-items-center rounded-xl ${selected ? 'bg-indigo-500 text-white' : 'bg-zinc-100 text-zinc-400'}`}><Hash className="h-4 w-4" /></span>
                            <span className="min-w-0 flex-1 truncate text-sm font-semibold">{channel.name}</span>
                            {selected && <CheckCircle2 className="h-4 w-4 text-indigo-500" />}
                          </label>
                        );
                      })}
                    </fieldset>
                  )}

                  {currentStep.type === 'rules' && (
                    <div className="mt-7">
                      <div className="max-h-48 overflow-y-auto rounded-[22px] border border-black/[0.06] bg-white p-5 text-sm leading-6 text-zinc-600 shadow-sm whitespace-pre-wrap">
                        {communityRules?.trim() || 'No additional written community guidelines have been published.'}
                      </div>
                      <label className={`mt-3 flex cursor-pointer items-center gap-3 rounded-[20px] border bg-white p-4 text-sm font-semibold shadow-sm transition ${currentAnswer === true ? 'border-emerald-300 ring-4 ring-emerald-500/10' : 'border-black/[0.06]'}`}>
                        <input type="checkbox" checked={currentAnswer === true} onChange={(event) => setAnswer(event.target.checked)} className="h-5 w-5 accent-emerald-600" />
                        I agree to follow these community guidelines.
                      </label>
                    </div>
                  )}
                </motion.div>
              </AnimatePresence>
            </div>

            <div className="flex items-center justify-between gap-3 border-t border-black/[0.06] bg-white/55 px-5 py-4 backdrop-blur-xl sm:px-8">
              <button type="button" onClick={goBack} disabled={stepIndex === 0 || saving} className="inline-flex min-h-12 items-center gap-2 rounded-full px-4 text-sm font-semibold text-zinc-500 transition hover:bg-white disabled:opacity-30">
                <ArrowLeft className="h-4 w-4" /> Back
              </button>
              <button
                type="button"
                onClick={continueFlow}
                disabled={!canContinue || saving}
                className="inline-flex min-h-12 min-w-36 items-center justify-center gap-2 rounded-full bg-zinc-950 px-6 text-sm font-semibold text-white shadow-lg transition hover:bg-black disabled:cursor-not-allowed disabled:opacity-35"
              >
                {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : stepIndex === flow.steps.length - 1 ? <Check className="h-4 w-4" /> : <ArrowRight className="h-4 w-4" />}
                {stepIndex === flow.steps.length - 1 ? 'Enter community' : 'Continue'}
              </button>
            </div>
          </main>
        </motion.div>
      </div>
    </AnimatePresence>
  );
};

